with account_stats as (select account_id, round(stddev(amount), 2) as stddev_amount, count(case when merchant = 'Lazada' then 1 end) as lazada_count from transactions group by account_id) select accounts.id, accounts.account_type, accounts.status, account_stats.stddev_amount, account_stats.lazada_count from accounts inner join account_stats on accounts.id = account_stats.account_id
